const keys=['problem','solution','approach','proof','impact','ask'];
const clean=(v,n=1000)=>typeof v==='string'?v.replace(/\0/g,'').trim().slice(0,n):'';
export const sectionNames={problem:'Problem',solution:'Solution',approach:'Approach',proof:'Evidence',impact:'Impact',ask:'Ask'};
export function signature(value){let h=2166136261;for(const c of String(value)){h=Math.imul(h^c.charCodeAt(0),16777619);}return (h>>>0).toString(16);}
export function normalizePreparation(raw={}){
 raw=raw&&typeof raw==='object'?raw:{};
 return {requirements:(Array.isArray(raw.requirements)?raw.requirements:[]).slice(0,20).filter(x=>x&&clean(x.title)).map(x=>({id:clean(x.id,80),title:clean(x.title,180),source:clean(x.source,1000),quote:clean(x.quote,1600),section:keys.includes(x.section)?x.section:'problem',weight:Math.min(100,Math.max(0,Number(x.weight)||0)),reviewed:clean(x.reviewed,100)})),tasks:(Array.isArray(raw.tasks)?raw.tasks:[]).slice(0,30).filter(x=>x&&clean(x.title)).map(x=>({id:clean(x.id,80),title:clean(x.title,180),owner:clean(x.owner,80),due:/^\d{4}-\d{2}-\d{2}$/.test(x.due)?x.due:'',done:x.done===true})),speakers:Object.fromEntries(keys.map(k=>[k,clean(raw.speakers?.[k],80)])),duration:[60,120,180,300,600].includes(Number(raw.duration))?Number(raw.duration):180,demo:clean(raw.demo,1600),fallback:clean(raw.fallback,1600),feedback:(Array.isArray(raw.feedback)?raw.feedback:[]).slice(0,20).filter(x=>x&&clean(x.note)).map(x=>({id:clean(x.id,80),section:keys.includes(x.section)?x.section:'problem',note:clean(x.note,1600),author:clean(x.author,80),done:x.done===true,at:clean(x.at,100)})),portal:clean(raw.portal,1000),receipt:clean(raw.receipt,1000)};
}
export function requirementSignature(r,p){return signature(JSON.stringify([r.title,r.source,r.quote,r.section,r.weight,p.event,p[r.section]]));}
export function requirementState(r,p){if(!r.source||!r.quote)return 'Source needed';if(!String(p[r.section]||'').trim())return 'Slide missing';return r.reviewed===requirementSignature(r,p)?'Reviewed by you':r.reviewed?'Draft changed · review again':'Needs your review';}
export function runOfShow(p){const prep=normalizePreparation(p.preparation);const weights=[.18,.22,.22,.16,.12,.10];let elapsed=0;return keys.map((key,i)=>{const duration=i===5?prep.duration-elapsed:Math.floor(prep.duration*weights[i]);const start=elapsed;elapsed+=duration;const script=String(p.notes?.[key]||p[key]||'').trim();const words=script.split(/\s+/).filter(Boolean).length;return {key,title:sectionNames[key],speaker:prep.speakers[key],start,end:elapsed,duration,script,words,estimated:Math.ceil(words/130*60),over:words/130*60>duration};});}
export function preparationSummary(p){const prep=normalizePreparation(p.preparation);return {requirements:prep.requirements.length,reviewed:prep.requirements.filter(r=>requirementState(r,p)==='Reviewed by you').length,tasks:prep.tasks.length,done:prep.tasks.filter(t=>t.done).length,feedback:prep.feedback.filter(f=>!f.done).length,overTime:runOfShow(p).filter(s=>s.over).length};}
export function challengeQuestions(p){const prep=normalizePreparation(p.preparation);return [...prep.requirements.map(r=>({section:r.section,question:`How does your ${sectionNames[r.section].toLowerCase()} address “${r.title}”?`,context:r.quote||'Add the organizer’s wording to make this question more specific.'})),{section:'proof',question:'Which claim in this pitch could you demonstrate or substantiate right now?',context:p.proof||'No evidence section supplied.'},{section:'approach',question:'What would you show if the live demo failed?',context:prep.fallback||'No demo fallback has been planned.'},{section:'ask',question:'What will the requested support let you do next?',context:p.ask||'No next step supplied.'}].slice(0,23);}
export function preparationReport(p){const prep=normalizePreparation(p.preparation);return `DAY-ZERO / PREPARATION WORKBOOK\n${p.name}\n${p.event||'Event not selected'}\n\nREQUIREMENT MAP\n${prep.requirements.map(r=>`${r.title} (${r.weight||'unspecified'} weight) → ${sectionNames[r.section]}\nOrganizer wording: ${r.quote||'Missing'}\nSource: ${r.source||'Missing'}\nStatus: ${requirementState(r,p)}\nDraft: ${p[r.section]||'Missing'}\n`).join('\n')}\nTEAM TASKS\n${prep.tasks.map(t=>`[${t.done?'x':' '}] ${t.title} / ${t.owner||'Unassigned'} / ${t.due||'No date'}`).join('\n')}\nRUN OF SHOW / ${prep.duration} seconds\n${runOfShow(p).map(s=>`${s.start}–${s.end}s / ${s.title} / ${s.speaker||'Unassigned'}\n${s.script||'[ADD SCRIPT]'}\n${s.over?'Estimated script exceeds its time slot.':''}`).join('\n\n')}\nDEMO\n${prep.demo||'Not planned'}\nFALLBACK\n${prep.fallback||'Not planned'}\n\nREVIEW QUESTIONS\n${challengeQuestions(p).map(q=>q.question+'\nContext: '+q.context).join('\n\n')}\n\nMENTOR NOTES\n${prep.feedback.map(f=>`[${f.done?'Resolved':'Open'}] ${f.author||'Reviewer'} / ${sectionNames[f.section]}: ${f.note}`).join('\n')}\n\nSUBMISSION RECORD\nPortal: ${prep.portal||'Not supplied'}\nReceipt / reference: ${prep.receipt||'Not recorded'}\n\nUser-supplied requirements and reviews. No automated official-source verification, AI jury, eligibility certification, or submission has been performed.\n`;
}
